function errorHandler(response) {
  let data = null;
  let error = null;
  let errMsg = null;
  let errorCode = null;
  let url = null;
  const metricsData = {
    myaadhaar_api_failure: 1
  };
  if (response && response.status !== 200) {
    // TelemetryService.metrics(metricsData);
    return {
      data: null,
      error: "Unexpected Error occured, please try again later !!"
    };
  }
  if (response?.data?.status === "Success" || response?.data?.status === "SUCCESS") {
    data = response?.data?.responseData;
    errMsg = data?.message;
  } else {
    if (response?.data?.errorCode) {
      // response?.data?.errorDetails && TelemetryService.metrics(metricsData);
      errMsg = response?.data?.errorDetails?.messageLocal ? response?.data?.errorDetails?.messageLocal : response?.data?.errorDetails?.messageEnglish;
      error = errMsg + " (" + response?.data?.errorCode + ")";
      errorCode = response?.data?.errorCode;
      url = response?.config?.url;
    } else {
      // response?.data?.errorDetails && TelemetryService.metrics(metricsData);
      error = response?.data?.errorDetails?.messageLocal ? response?.data?.errorDetails?.messageLocal : response?.data?.errorDetails?.messageEnglish;
    }
  }
  return {
    data,
    error,
    errMsg,
    url,
    errorCode
  };
}
